import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import nodemailer from "npm:nodemailer@6.9.16";

// ============================================================
// fms-hr-meeting
//
// Powers the employee's "Book a Meeting with HR" page
// (/book-hr-meeting?token=<booking_token>) generated by the
// fms-hr-warning edge function when a warning is emailed.
//
// Operations:
//   get_booking  — validate token, return warning/employee summary
//   book_meeting — save the requested meeting date/time/type/message
//                  onto fms_hr_warnings (meeting_status = 'pending')
//
// The caller is an unauthenticated employee clicking an emailed
// link, so requests are authenticated by the booking_token column
// instead of a JWT.
// ============================================================

// CORS allowlist
const getAllowedOrigin = (requestOrigin: string | null): string => {
  const envOrigins = (Deno.env.get('ALLOWED_ORIGINS') || Deno.env.get('ALLOWED_ORIGIN') || '')
    .split(',')
    .map((o) => o.trim())
    .filter(Boolean);

  if (requestOrigin) {
    if (envOrigins.includes(requestOrigin)) return requestOrigin;
    if (
      requestOrigin.startsWith('http://localhost:') ||
      requestOrigin.startsWith('https://localhost:')
    ) {
      return requestOrigin;
    }
  }

  if (envOrigins.length === 1) return envOrigins[0];

  return '';
};

const createCorsHeaders = (requestOrigin: string | null) => ({
  'Access-Control-Allow-Origin': getAllowedOrigin(requestOrigin),
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Credentials': 'true',
});

// Best-effort heads-up email to HR using the SAME company SMTP
// transport as every other HR email. Failures never block the booking.
async function notifyHR(subject: string, html: string) {
  const fromEmail =
    Deno.env.get('SMTP_USER') || 'zulaigah.benjamin@maharajasspices.co.za';
  const smtpPass = Deno.env.get('SMTP_PASS');
  if (!smtpPass) {
    console.error('[fms-hr-meeting] SMTP_PASS not configured — skipping HR notification');
    return;
  }

  const port = Number(Deno.env.get('SMTP_PORT') || '465');

  try {
    const transporter = nodemailer.createTransport({
      host: Deno.env.get('SMTP_HOST') || 'mail.maharajasspices.co.za',
      port,
      secure: port === 465,
      auth: { user: fromEmail, pass: smtpPass },
    });

    await transporter.sendMail({
      from: `"Maharaja Spices HR" <${fromEmail}>`,
      to: fromEmail,
      replyTo: fromEmail,
      subject,
      html,
    });
    console.log('[fms-hr-meeting] HR notification sent');
  } catch (smtpErr) {
    console.error('[fms-hr-meeting] SMTP error:', smtpErr);
  }
}

serve(async (req) => {
  const origin = req.headers.get('origin');
  const corsHeaders = createCorsHeaders(origin);

  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

    // Admin client — bypasses RLS. The booking token is the credential.
    const adminClient = createClient(supabaseUrl, supabaseServiceKey, {
      auth: { autoRefreshToken: false, persistSession: false },
    });

    const body = await req.json();
    const { operation, token } = body;

    if (!token || typeof token !== 'string') {
      return new Response(
        JSON.stringify({ success: false, error: 'This meeting booking link is invalid or missing its security token.' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // Look up the warning this booking link belongs to
    const { data: warning, error: warningError } = await adminClient
      .from('fms_hr_warnings')
      .select(`
        id,
        warning_type,
        reason,
        issued_at,
        meeting_status,
        meeting_date,
        employee:employee_id ( first_name, last_name, employee_number, email )
      `)
      .eq('booking_token', token)
      .maybeSingle();

    if (warningError) {
      console.error('[fms-hr-meeting] Warning lookup error:', warningError);
      return new Response(
        JSON.stringify({ success: false, error: 'Unable to load the meeting booking page. Please try again.' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    if (!warning) {
      return new Response(
        JSON.stringify({ success: false, error: 'This booking link is invalid or has expired.' }),
        { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const employee = Array.isArray(warning.employee) ? warning.employee[0] : warning.employee;
    const employeeName = employee
      ? `${employee.first_name ?? ''} ${employee.last_name ?? ''}`.trim()
      : 'Unknown employee';

    // ----------------------------------------------------------
    // GET BOOKING — summary shown on the booking page
    // ----------------------------------------------------------
    if (operation === 'get_booking') {
      return new Response(
        JSON.stringify({
          success: true,
          booking: {
            employee_name: employeeName,
            employee_number: employee?.employee_number ?? null,
            warning_type: warning.warning_type,
            warning_date: warning.issued_at,
            meeting_status: warning.meeting_status,
            existing_meeting_date: warning.meeting_date,
          },
        }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // ----------------------------------------------------------
    // BOOK MEETING — save the employee's requested slot
    // ----------------------------------------------------------
    if (operation === 'book_meeting') {
      const { meeting_date: meetingDate, meeting_start_time: meetingStartTime } = body;

      if (!meetingDate || !meetingStartTime) {
        return new Response(
          JSON.stringify({ success: false, error: 'Please select a meeting date and time.' }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // Combine date + time into a proper UTC timestamp
      const isoDate = new Date(`${meetingDate}T${meetingStartTime}`).toISOString();

      const { error: updateError } = await adminClient
        .from('fms_hr_warnings')
        .update({
          meeting_date: isoDate,
          meeting_status: 'pending',
          meeting_requested: true,
          meeting_type: body.meeting_type === 'online' ? 'online' : 'in_person',
          meeting_message: body.meeting_message || null,
        })
        .eq('id', warning.id);

      if (updateError) {
        console.error('[fms-hr-meeting] Booking update error:', updateError);
        return new Response(
          JSON.stringify({ success: false, error: 'Unable to book the meeting. Please try again.' }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // Best-effort email heads-up to HR (never blocks the booking)
      const fmt = new Date(isoDate).toLocaleString('en-GB', {
        weekday: 'long', day: '2-digit', month: 'long', year: 'numeric',
        hour: '2-digit', minute: '2-digit',
      });
      const safeMessage = body.meeting_message
        ? String(body.meeting_message).replace(/</g, '&lt;')
        : '';
      await notifyHR(
        `Meeting requested — ${employeeName} (${warning.warning_type} warning)`,
        `
          <p><strong>${employeeName}</strong>${employee?.employee_number ? ` (${employee.employee_number})` : ''} has requested a meeting regarding their <strong>${warning.warning_type}</strong> warning.</p>
          <p><strong>Requested time:</strong> ${fmt}</p>
          <p><strong>Type:</strong> ${body.meeting_type === 'online' ? 'Online' : 'In person'}</p>
          ${safeMessage ? `<p><strong>Message:</strong><br/>${safeMessage}</p>` : ''}
          <p>Please confirm or reschedule this meeting from the HR dashboard.</p>
        `
      );

      return new Response(
        JSON.stringify({ success: true }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    return new Response(
      JSON.stringify({ success: false, error: 'Unknown operation' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (err) {
    console.error('[fms-hr-meeting] Unexpected error:', err);
    return new Response(
      JSON.stringify({ success: false, error: 'Something went wrong while processing the booking.' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

